"""Audit-derived tables and facts; original measurements are read without alteration."""
from pathlib import Path
import csv,hashlib,heapq,json,math,shutil,sqlite3,sys,tempfile,zipfile
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT/'scripts'))
import study_structural_interventions as ssi

def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write_json(p,data):p.write_text(json.dumps(data,indent=2)+'\n')
def table(path,caption,label,columns,header,rows,foot=''):
    out=['% Generated by scripts/reconcile_full_manuscript.py',r'\begin{table*}[t]',r'\centering',r'\footnotesize',r'\caption{'+caption+'}',r'\label{'+label+'}',r'\begin{tabular}{'+columns+'}',r'\toprule',header+r'\\',r'\midrule']
    if label=='tab:q1_incident_case_study':
        out.insert(-4,r'\resizebox{\textwidth}{!}{%')
    out += [' & '.join(str(x) for x in row)+r'\\' for row in rows]
    out += [r'\bottomrule',r'\end{tabular}']
    if label=='tab:q1_incident_case_study':out += ['}']
    if foot:out += [r'\par\smallskip\begin{minipage}{0.98\textwidth}\footnotesize '+foot+r'\end{minipage}']
    out += [r'\end{table*}','']
    path.write_text('\n'.join(out))

def main():
    out=ROOT/'manuscript_q1/results';tbl=ROOT/'manuscript_q1/tables'
    baseline=json.loads((ROOT/'manuscript/results/structural_interventions/results.json').read_text())
    fidelity=json.loads((ROOT/'manuscript/results/graph_validity/summary.json').read_text())
    temporal=json.loads((ROOT/'platform/research/74_bounded_recursive_registry_semver_graph_manifest.json').read_text())
    availability=json.loads((ROOT/'platform/research/95_release_authority_metadata_availability_audit.json').read_text())
    access=json.loads((ROOT/'platform/research/97_official_npm_provenance_attestation_access_assessment.json').read_text())
    rows=[];methods=['portfolio','sum_package_reach','max_package_reach','exact_union','greedy_coverage']
    for b in (1,5,10,25,50,100):
        det=[next(r for r in baseline['deterministic_curves'] if r['endpoint']=='workflow_repositories' and r['method']==m and r['budget']==b) for m in methods]
        rnd=next(r for r in baseline['random_summary'] if r['endpoint']=='workflow_repositories' and r['budget']==b)
        for metric,key,factor in [('C (\\%)','coverage_fraction_observed',100),('H (\\%)','scenario_exposure_reduction_fraction',100),('P','fully_protected_endpoints',1)]:
            vals=[f'{factor*r[key]:.2f}' if factor==100 else f'{r[key]:,}' for r in det]
            mean=factor*rnd[key+'_mean'];mcse=factor*rnd[key+'_sd']/math.sqrt(rnd['trials'])
            rows.append([b,metric,*vals,f'{mean:.2f} $\\pm$ {mcse:.2f}'])
    table(tbl/'q1_multi_budget_table.tex','Workflow-repository outcomes from the retained baseline experiment. Random entries are 200-order sample means and Monte Carlo standard errors, not population confidence intervals.','tab:multi_budget_comparison','llrrrrrr','Budget & Metric & Portfolio & Sum & Max & Exact union & Greedy & Random mean $\\pm$ MCSE',rows)
    with tempfile.TemporaryDirectory() as tmp:
        db=Path(tmp)/'npm.db'
        with zipfile.ZipFile(ROOT/'data/npm_ecosystem.db.zip') as z,z.open('npm_ecosystem.db') as src,db.open('wb') as dst:shutil.copyfileobj(src,dst)
        conn=sqlite3.connect(f'file:{db}?mode=ro&immutable=1',uri=True)
        names,ids,port,pm,adj,wf,ch,rn,wn,sn,pop=ssi.load_data(conn)
        comp,mem,edges,topo=ssi.scc_condensation(adj)
        pkg=ssi.propagate_endpoint_bits(comp,mem,edges,topo,wn);ep=ssi.endpoint_data(pkg,port)
        vp,vr,vs,vm=ssi.version_continuous_representation(conn,names,pm,wn);vep=ssi.endpoint_data(vr,port)
        identity={name:i for i,(name,_) in enumerate(ids)};M=len(ids)
        order_union=sorted(range(M),key=lambda m:(-ep['sizes'][m],m));order_version=sorted(range(M),key=lambda m:(-vep['sizes'][m],m))
        order_port=sorted(range(M),key=lambda m:(-len(port[m]),m))
        greedy,_=ssi.lazy_greedy(ep['masks'],range(M),range(M),100)
        heap=[(-(0.5*ep['sizes'][m]/7171+0.5*ep['sizes'][m]/ep['total_pairs']),m) for m in range(M)];heapq.heapify(heap)
        hybrid=[];covered=0
        while heap:
            _,m=heapq.heappop(heap);gain=.5*(ep['masks'][m]&~covered).bit_count()/7171+.5*ep['sizes'][m]/ep['total_pairs']
            key=(-gain,m)
            if not heap or key<=heap[0]:hybrid.append(m);covered|=ep['masks'][m]
            else:heapq.heappush(heap,key)
        ranks={name:{ids[m][0]:i+1 for i,m in enumerate(order)} for name,order in [('portfolio',order_port),('union',order_union),('version_union',order_version),('greedy',greedy),('hybrid',hybrid)]}
        facts={}
        for user in ('qix','sindresorhus','tootallnate'):
            m=identity[user];seen=set();todo=list(port[m])
            while todo:
                p=todo.pop()
                if p in seen:continue
                seen.add(p);todo.extend(adj[p]-seen)
            bfs=ssi.union(wn[p] for p in seen)
            assert bfs==ep['masks'][m], 'Independent BFS/bitset disagreement'
            facts[user]={'workflow_name_reach':ep['sizes'][m],'workflow_version_reach':vep['sizes'][m],
                         'portfolio_size':len(port[m]),'ranks':{name:r.get(user,'>100') for name,r in ranks.items()}}
        q=identity['qix'];a=identity['sindresorhus'];b=identity['tootallnate']
        facts['qix']['not_reached_by_sindresorhus']=(ep['masks'][q]&~ep['masks'][a]).bit_count()
        facts['qix']['overlap_with_sindresorhus_or_tootallnate']=(ep['masks'][q]&(ep['masks'][a]|ep['masks'][b])).bit_count()
        old=json.loads((ROOT/'manuscript_q1/config/incident_case_records.json').read_text())['records']
        per_package={r['package_name']:r for r in csv.DictReader((ROOT/'manuscript/results/graph_validity/per_package.csv').open())}
        incidents=[];table_rows=[]
        for row in old:
            label=row['package'];package=label.split(' ')[0];user=row['primary_maintainer'];mcount=conn.execute('SELECT COUNT(*) FROM package_maintainers WHERE package_name=?',(package,)).fetchone()[0]
            dr,tr=conn.execute('SELECT direct_dependents,transitive_dependents FROM package_metrics WHERE package_name=?',(package,)).fetchone()
            row={**row,'reach_name':int(per_package[package]['workflow_repository_reach']),'reach_vc':int(per_package[package]['version_continuous_workflow_repository_reach'])}
            current={**row,'maintainer_count':mcount,'direct_dependents':dr,'transitive_dependents':tr,
                     'portfolio_rank':ranks['portfolio'][user],'greedy_rank':ranks['greedy'].get(user,'>100'),
                     'union_name_rank':ranks['union'][user],'pareto_p50_rank':ranks['hybrid'][user]}
            current.pop('direct_deps',None);current.pop('transitive_deps',None);incidents.append(current)
            rank=lambda x:r'\#'+format(x,',') if isinstance(x,int) else r'\#>100'
            table_rows.append([r'\texttt{'+label+'}',r'\texttt{'+user+'} ('+str(mcount)+')',f"{int(row['reach_name']):,}",f"{int(row['reach_vc']):,}",rank(current['portfolio_rank']),rank(current['greedy_rank']),rank(current['union_name_rank']),rank(current['pareto_p50_rank'])])
        table(tbl/'q1_incident_case_study_table.tex','Observed workflow-repository reach and account rankings for 16 incident-associated records (15 package names). Reach and ranks use the retained cross-sectional graph, not pre-event installations.','tab:q1_incident_case_study','llrrrrrr','Package / record & Account (count) & Name reach & Version reach & Portfolio & Greedy & Union & Hybrid',table_rows, r'Every account rank uses workflow-associated repository endpoints. The parenthesized value counts observed maintainers of that package. Membership is not evidence of historical publishing authority. Version labels and dependency counts are retained in the companion CSV. Package reach excludes the root; account portfolios include eligible seeds.')
        shutil.copy2(tbl/'q1_incident_case_study_table.tex',ROOT/'manuscript/results/q1_journal/q1_incident_case_study_table.tex')
    bins=json.loads((ROOT/'manuscript_q1/results/quorum_reproducibility.json').read_text())['cardinality_histograms'][0]['counts']
    source_stats={'mean_nonempty':sum(n*c for n,t,c in bins)/7158,'max':max(n for n,t,c in bins),'nonempty':7158,'pairs':462170}
    s=temporal['summary'];roots=s['perRoot']
    attempts=list(csv.DictReader((ROOT/'platform/research/74_bounded_recursive_registry_semver_graph_edges.csv').open()))
    unresolved=sum(r['target_resolution_status']!='resolved_cutoff_semver_range' for r in attempts);resolved=len(attempts)-unresolved;ratio=100*resolved/len(attempts)
    assert len(attempts)==s['reconstructedEdges'] and unresolved==s['unresolvedEdges']
    unique_roots=len({(r['recordId'],r['rootNode'],r['cutoffUtc']) for r in roots})
    trows=[['Retained root records',len(roots)],['Distinct event/root/cutoff tuples',unique_roots],['Recorded edge attempts',f'{len(attempts):,}'],['Resolved recorded edges',f'{resolved:,}'],['Node counts summed over roots',f"{s['reconstructedNodesAcrossRoots']:,}"],['Unresolved expansions',unresolved],['Resolved share of recorded attempts',f'{ratio:.2f}\\%'],['Maximum expansion depth',temporal['bounds']['maxDepth']],['Node cap per root',temporal['bounds']['maxNodesPerRoot']],['Roots reaching cap',sum(bool(x['nodeCapReached']) for x in roots)]]
    table(tbl/'q1_temporal_reconstruction_table.tex','Retained bounded registry-SemVer reconstruction manifest. The recorded resolution share is conditional on attempted expansions within the bounds.','tab:q1_temporal_reconstruction','lr','Recorded dimension & Value',trows,
          r'Only regular dependencies are included; depth is capped at three and nodes at 250 per root. Highest retained cutoff-valid satisfying versions are used. These are bounded approximations, not lockfile reconstructions or completeness guarantees. Raw-response checksums establish retained-object identity, not publisher authenticity.')
    summary=availability['summary'];mapping=[('Retained selected-version objects','exactPreEventSourceSnapshots'),('Immediate predecessor available','predecessorAvailable'),('Repository-field comparison available','repositoryDescriptorComparisonAvailable'),('gitHead-field comparison available','gitHeadComparisonAvailable'),('publishConfig comparison available','publishConfigComparisonAvailable'),('Selected dist.integrity present','selectedDistIntegrityPresent'),('Selected embedded maintainers present','selectedEmbeddedMaintainersPresent')]
    arows=[[title,summary[key],f'{100*summary[key]/45:.1f}\\%'] for title,key in mapping]
    table(tbl/'q1_release_authority_table.tex','Field availability in 45 retained pre-event version-object records. Comparison availability is not continuity, equality, or authenticated release authority.','tab:q1_release_authority','lrr','Metadata availability & Count & Share',arows,
          r'The 45 records include a repeated event/root/cutoff tuple; they are not independent incidents. Embedded maintainer metadata is not a signature. No version-specific provenance endpoint requests, bundle retrievals, signature verifications, or attestation-state classifications were performed. Historical attestation presence/absence is unknown, not 0/45 absent.')
    for name in ('q1_temporal_reconstruction_table.tex','q1_release_authority_table.tex'):
        shutil.copy2(tbl/name,ROOT/'manuscript/results/q1_journal'/name)
    write_json(out/'incident_workflow_reconciliation.json',incidents)
    with (ROOT/'manuscript/results/q1_journal/q1_incident_case_study.csv').open('w',newline='') as f:
        writer=csv.DictWriter(f,fieldnames=incidents[0],lineterminator='\n');writer.writeheader();writer.writerows(incidents)
    weights=json.loads((ROOT/'manuscript/results/q1_journal_experiments.json').read_text())['heterogeneous_weights']
    wrows=[]
    labels={'Exact Union (Unweighted)':'Exact union','Greedy Coverage':'Greedy coverage','Portfolio Size':'Portfolio','Pareto Hybrid (alpha=0.50)':'Hybrid (0.50)','Weight-Aware Sole Optimum':'Account-sole aware','Weight-Aware Log Optimum':'Log-portfolio aware','Weight-Aware Package-Sole Optimum':'Package-sole aware'}
    for strategy,v in weights.items():
        wrows.append([labels[strategy],f"{v['C']:,}",f"{v['H_uniform_pct']:.2f}",f"{v['H_sole_pct']:.2f}",f"{v['H_log_pct']:.2f}",f"{v['H_pkg_sole_pct']:.2f}",v['P']])
    table(tbl/'q1_heterogeneous_weights_table.tex','Budget-100 outcomes under assumed weights. Each H column has its own stipulated denominator; weights are not estimated compromise probabilities.','tab:q1_heterogeneous_weights','lrrrrrr',r'Selection & C & H (\%) & Account-sole (\%) & Log (\%) & Package-sole (\%) & P',wrows)
    shutil.copy2(tbl/'q1_heterogeneous_weights_table.tex',ROOT/'manuscript/results/q1_journal/q1_heterogeneous_weights_table.tex')
    source_files=['data/npm_ecosystem.db.zip','manuscript/results/structural_interventions/results.json','manuscript/results/graph_validity/summary.json','platform/research/74_bounded_recursive_registry_semver_graph_manifest.json','platform/research/74_bounded_recursive_registry_semver_graph_edges.csv','manuscript/results/graph_validity/per_package.csv','platform/research/95_release_authority_metadata_availability_audit.json','platform/research/97_official_npm_provenance_attestation_access_assessment.json','manuscript/results/q1_journal_experiments.json','manuscript_q1/config/incident_case_records.json','scripts/reconcile_full_manuscript.py']
    facts_out={'focal_maintainers':facts,'source_cardinality':source_stats,'scc':fidelity['scc'],
               'temporal':{'resolved':resolved,'unresolved':unresolved,'attempted_share_pct':ratio,'nodes_sum':s['reconstructedNodesAcrossRoots'],'capped_roots':sum(bool(x['nodeCapReached']) for x in roots),'recorded_attempts':len(attempts),'root_records':len(roots),'distinct_root_tuples':unique_roots},
               'availability':summary,'attestation_classification':access['decision'],'budget_table_rows':rows,
               'source_sha256':{name:sha(ROOT/name) for name in source_files}}
    write_json(out/'full_revision_evidence.json',facts_out)
    qfacts=facts['qix']
    macros={'QixPortfolio':str(qfacts['portfolio_size']),'QixNameReach':f"{qfacts['workflow_name_reach']:,}",'QixVersionReach':f"{qfacts['workflow_version_reach']:,}",'QixUnionRank':str(qfacts['ranks']['union']),'QixVersionRank':str(qfacts['ranks']['version_union']),'QixHybridRank':str(qfacts['ranks']['hybrid']),'QixOutsideSindresorhus':str(qfacts['not_reached_by_sindresorhus'])}
    tex='% Generated from read-only workflow-repository reconciliation.\n'+''.join('\\newcommand{\\'+k+'}{'+v+'}\n' for k,v in macros.items())
    (ROOT/'manuscript/results/reconciliation_numbers.tex').write_text(tex)
    (ROOT/'manuscript_q1/config/reconciliation_numbers.tex').write_text(tex)
    print(json.dumps({'focal':facts,'source_cardinality':source_stats,'temporal_attempt_share_pct':ratio},indent=2))

if __name__=='__main__':main()
